import Foundation
import Vapor

// MARK: - Models
struct User: Content, Authenticatable {
    let id: UUID
    let username: String
    let role: Role

    enum Role: String, Codable {
        case admin
        case editor
        case viewer
    }
}

struct TaskPayload: Content {
    let name: String
    let description: String
    let metadata: String? // Base64-encoded supplementary data
}

// MARK: - Middleware
struct RoleGuardMiddleware: AsyncMiddleware {
    let allowedRoles: [User.Role]

    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let user = request.auth.get(User.self) else {
            throw Abort(.unauthorized)
        }
        guard allowedRoles.contains(user.role) else {
            throw Abort(.forbidden)
        }
        return try await next.respond(to: request)
    }
}

// MARK: - Serialization Layer
protocol SerializationStrategy {
    func deserialize(_ data: Data) throws -> Any
}

class JSONStrategy: SerializationStrategy {
    func deserialize(_ data: Data) throws -> Any {
        return try JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed])
    }
}

class ArchiveStrategy: SerializationStrategy {
    func deserialize(_ data: Data) throws -> Any {
        // NSKeyedUnarchiver for backward-compatible rich object graphs
        let unarchiver = try NSKeyedUnarchiver(forReadingFrom: data)
        unarchiver.requiresSecureCoding = false
        let result = unarchiver.decodeObject(forKey: NSKeyedArchiveRootObjectKey)
        unarchiver.finishDecoding()
        guard let obj = result else {
            throw Abort(.badRequest, reason: "Failed to decode archive")
        }
        return obj
    }
}

class SerializationFactory {
    static func strategy(for contentType: String?) -> SerializationStrategy {
        switch contentType {
        case "application/x-plist", "application/x-apple-archive":
            return ArchiveStrategy()
        default:
            return JSONStrategy()
        }
    }
}

// MARK: - Service Layer
class TaskService {
    func processMetadata(from payload: TaskPayload, contentHint: String?) throws -> [String: Any] {
        guard let metadataB64 = payload.metadata,
              let rawData = Data(base64Encoded: metadataB64) else {
            return [:]
        }

        let strategy = SerializationFactory.strategy(for: contentHint)
        let decoded = try strategy.deserialize(rawData)

        guard let dict = decoded as? [String: Any] else {
            throw Abort(.badRequest, reason: "Metadata must be a dictionary")
        }
        return dict
    }
}

// MARK: - Routes
func routes(_ app: Application) throws {
    let taskService = TaskService()

    // Public health check
    app.get("health") { req -> String in
        return "OK"
    }

    // Protected task creation - editors and admins only
    let protected = app.grouped([
        UserAuthenticator(),
        RoleGuardMiddleware(allowedRoles: [.admin, .editor])
    ])

    protected.post("tasks") { req -> Response in
        let payload = try req.content.decode(TaskPayload.self)

        // The X-Metadata-Format header hints how to parse the metadata field
        let metadataFormat = req.headers.first(name: "X-Metadata-Format")

        let enrichedMetadata = try taskService.processMetadata(
            from: payload,
            contentHint: metadataFormat
        }

        // Store task with enriched metadata
        let responseData: [String: String] = [
            "status": "created",
            "name": payload.name,
            "metadataKeys": enrichedMetadata.keys.joined(separator: ",")
        ]

        return try await responseData.encodeResponse(for: req)
    }

    // Admin-only: bulk import with archive support
    let adminOnly = app.grouped([
        UserAuthenticator(),
        RoleGuardMiddleware(allowedRoles: [.admin])
    ])

    adminOnly.post("tasks", "bulk") { req -> Response in
        let payload = try req.content.decode([TaskPayload].self)
        var results: [[String: Any]] = []

        for task in payload {
            let metadata = try taskService.processMetadata(
                from: task,
                contentHint: req.headers.first(name: "X-Metadata-Format")
            )
            results.append(["name": task.name, "keys": metadata.keys.count])
        }

        return try await ["imported": results.count].encodeResponse(for: req)
    }
}

// MARK: - Auth Helper
struct UserAuthenticator: AsyncBearerAuthenticator {
    func authenticate(bearer: BearerAuthorization, for request: Request) async throws {
        // In production, validate JWT and extract user
        guard let tokenData = Data(base64Encoded: bearer.token),
              let claims = try? JSONDecoder().decode(User.self, from: tokenData) else {
            return
        }
        request.auth.login(claims)
    }
}
